dtsPropsFor.ChipInput:
/** Id for the text input, so a <label htmlFor> can point at it. */
  id: string;
  /** Names one entry, for the buttons: "medication" gives "Add medication" and "Remove …". */
  noun: string;
  /** Controlled value: the chips added so far, plus any text typed but not yet added. */
  value: { items: string[]; typing: string };
  onChange: (c: { items: string[]; typing: string }) => void;

dtsPropsFor.Masthead:
/** Which step or info page is showing. Drives the current nav link, and the Stepper
   * (which is hidden on the info pages: history, privacy, references, data). */
  view: "contribute" | "questions" | "setup" | "screen" | "distance" | "motion" | "form" | "results" | "history" | "privacy" | "references" | "data";
